/* Local semantic search. Loads the packed potion-base-8M model and the
 * precomputed chunk vectors only when the reader searches, then embeds the
 * query in the browser (about 0.3 ms) and ranks the chunks by cosine
 * similarity. No network round-trip, no API key, no GPU.
 *
 * The index is generated by tools/build_semantic_index.py.
 */
(function() {
	'use strict';

	var MODEL_URL = new URL('vendor/model2vec/models/potion-base-8M.bin', document.baseURI).href;
	var MODULE_URL = new URL('vendor/model2vec/model.js', document.baseURI).href;
	var INDEX_URL = new URL('semantic_index.json', document.baseURI).href;
	var VECTOR_URL = new URL('semantic_vectors.bin', document.baseURI).href;

	var state = null;
	var loading = null;
	var failed = false;

	function load() {
		if (state) return Promise.resolve(state);
		if (failed) return Promise.reject(new Error('semantic search unavailable'));
		if (loading) return loading;

		loading = Promise.all([
			import(MODULE_URL).then(function(mod) {
				return mod.StaticModel.load(MODEL_URL);
			}),
			fetch(INDEX_URL).then(function(response) {
				if (!response.ok) throw new Error('semantic index: HTTP ' + response.status);
				return response.json();
			}),
			fetch(VECTOR_URL).then(function(response) {
				if (!response.ok) throw new Error('semantic vectors: HTTP ' + response.status);
				return response.arrayBuffer();
			})
		]).then(function(parts) {
			var model = parts[0];
			var meta = parts[1];
			var parsed = parseVectors(parts[2], meta);
			state = {
				model: model,
				meta: meta,
				dims: parsed.dims,
				count: parsed.count,
				scales: parsed.scales,
				vectors: parsed.vectors
			};
			return state;
		}).catch(function(error) {
			failed = true;
			loading = null;
			console.warn('Semantic search unavailable:', error);
			throw error;
		});

		return loading;
	}

	function parseVectors(buffer, meta) {
		if (!buffer || buffer.byteLength < 16) throw new Error('semantic vectors are empty');
		var view = new DataView(buffer);
		var magic = view.getUint32(0, true);
		var version = view.getUint32(4, true);
		var count = view.getUint32(8, true);
		var dims = view.getUint32(12, true);
		if (magic !== 0x4D4E5356 || version !== 1) throw new Error('bad semantic vector header');
		if (count !== meta.chunks.length || dims !== meta.dims) throw new Error('semantic index and vectors disagree');
		var scaleOffset = 16;
		var vectorOffset = scaleOffset + count * 4;
		if (buffer.byteLength !== vectorOffset + count * dims) throw new Error('semantic vectors are truncated');
		return {
			count: count,
			dims: dims,
			scales: new Float32Array(buffer, scaleOffset, count),
			vectors: new Int8Array(buffer, vectorOffset, count * dims)
		};
	}

	function search(query, options) {
		if (!state) return [];
		return rank(state.meta, state, state.model.embed(query), options);
	}

	function rank(meta, parsed, queryVector, options) {
		options = options || {};
		var limit = options.limit || 60;
		var maxPerPage = options.maxPerPage || 5;
		var dims = parsed.dims;
		var count = parsed.count;
		var vectors = parsed.vectors;
		var scales = parsed.scales;
		var scores = new Float32Array(count);

		for (var i = 0; i < count; i++) {
			var offset = i * dims;
			var sum = 0;
			var d = 0;
			for (; d + 3 < dims; d += 4) {
				sum += vectors[offset + d] * queryVector[d]
					+ vectors[offset + d + 1] * queryVector[d + 1]
					+ vectors[offset + d + 2] * queryVector[d + 2]
					+ vectors[offset + d + 3] * queryVector[d + 3];
			}
			for (; d < dims; d++) sum += vectors[offset + d] * queryVector[d];
			scores[i] = sum * scales[i];
		}

		var candidates = topK(scores, Math.min(count, limit * 4));
		var results = [];
		var perPage = Object.create(null);
		var seenUrl = Object.create(null);
		for (var j = 0; j < candidates.length && results.length < limit; j++) {
			var index = candidates[j][1];
			var chunk = meta.chunks[index];
			if (!chunk) continue;
			var urlKey = chunk.u || (chunk.p + '|' + chunk.h);
			if (seenUrl[urlKey]) continue;
			var pageCount = perPage[chunk.p] || 0;
			if (pageCount >= maxPerPage) continue;
			seenUrl[urlKey] = true;
			perPage[chunk.p] = pageCount + 1;
			results.push(resultFrom(chunk, candidates[j][0]));
		}
		return results;
	}

	/* Fixed-size min-heap: the top k scores without allocating and sorting
	 * one pair per chunk. Returns [score, index] pairs, best first. */
	function topK(scores, k) {
		if (k >= scores.length) {
			var all = new Array(scores.length);
			for (var n = 0; n < scores.length; n++) all[n] = [scores[n], n];
			all.sort(function(a, b) { return b[0] - a[0]; });
			return all;
		}

		var heapScore = new Float32Array(k);
		var heapIndex = new Int32Array(k);
		var size = 0;

		function siftDown(start) {
			var i = start;
			for (;;) {
				var left = 2 * i + 1;
				var right = left + 1;
				var smallest = i;
				if (left < size && heapScore[left] < heapScore[smallest]) smallest = left;
				if (right < size && heapScore[right] < heapScore[smallest]) smallest = right;
				if (smallest === i) return;
				var score = heapScore[i];
				var index = heapIndex[i];
				heapScore[i] = heapScore[smallest];
				heapIndex[i] = heapIndex[smallest];
				heapScore[smallest] = score;
				heapIndex[smallest] = index;
				i = smallest;
			}
		}

		for (var i = 0; i < scores.length; i++) {
			var score = scores[i];
			if (size < k) {
				heapScore[size] = score;
				heapIndex[size] = i;
				size++;
				if (size === k) {
					for (var root = (size >> 1) - 1; root >= 0; root--) siftDown(root);
				}
			} else if (score > heapScore[0]) {
				heapScore[0] = score;
				heapIndex[0] = i;
				siftDown(0);
			}
		}

		var out = new Array(size);
		for (var position = size - 1; position >= 0; position--) {
			out[position] = [heapScore[0], heapIndex[0]];
			size--;
			if (size > 0) {
				heapScore[0] = heapScore[size];
				heapIndex[0] = heapIndex[size];
				siftDown(0);
			}
		}
		return out;
	}

	function resultFrom(chunk, score) {
		return {
			page: chunk.p,
			pageTitle: chunk.pt,
			type: chunk.t === 'page' ? 'content' : chunk.t,
			mode: 'semantic',
			semantic: true,
			title: chunk.h || chunk.pt,
			snippet: chunk.x,
			url: chunk.u,
			score: score,
			img: chunk.i || ''
		};
	}

	window.MNSemantic = {
		load: load,
		search: search,
		ready: function() { return state; }
	};

	if (typeof module !== 'undefined' && module.exports) {
		module.exports = {
			parseVectors: parseVectors,
			rank: rank,
			resultFrom: resultFrom
		};
	}
})();
